HEADER = '''// GENERATED by tools/i18n_catalogue.py -- do not edit by hand.
//
// The English string is the key; see src/i18n.h. A null translation means "not
// translated yet" and falls back to English at the call site, so a partial
// column ships safely.
#pragma once

namespace materializr {

struct TrEntry { const char* en; const char* tr; };

'''

FMT = __import__("re").compile(r"%[-+#0]*\d*(?:\.\d+)?(?:zu|ll?[du]|[sdifgxXuc])|%%")

def emit(path):
    seen = set()
    for en, tr in CAT:
        if en in seen:
            sys.exit("duplicate key in catalogue: %r" % en)
        seen.add(en)
        # A printf specifier mismatch between key and translation is a CRASH at
        # the call site (wrong arg count/type), not a cosmetic bug. Order
        # matters too: plain printf has no positional args on MSVC, so a
        # translation may not reorder them.
        want = FMT.findall(en)
        for code, v in tr.items():
            if v and FMT.findall(v) != want:
                sys.exit("format-specifier mismatch [%s] %r -> %r" % (code, en, v))
    out = [HEADER]
    for code in LANGS:
        # ASCII-only comment too: MSVC without /utf-8 can choke on stray high
        # bytes anywhere in the file, comments included.
        out.append("// --- %s ---\n" % LANG_ENGLISH[code])
        out.append("inline const TrEntry k%sCatalogue[] = {\n" % code.capitalize())
        n = 0
        for en, tr in CAT:
            v = tr.get(code, "")
            if not v:
                continue
            out.append('    { %s, %s },\n' % (cstr(en), cstr(v)))
            n += 1
        out.append("};\n")
        out.append("inline constexpr int k%sCount = %d;\n\n" % (code.capitalize(), n))
    out.append("} // namespace materializr\n")
    with open(path, "w", encoding="utf-8") as f:
        f.write("".join(out))
    return len(CAT)

def cstr(s):
    """C string literal with non-ASCII as explicit \\xNN UTF-8 bytes.

    Deliberate: MSVC without /utf-8 reads a raw UTF-8 source file in the host
    ANSI codepage and mangles every accent. Escaping the bytes makes the file
    pure ASCII, so it compiles identically on every toolchain with no build-flag
    dependency -- and this repo has been bitten by MSVC encoding before.
    """
    out = ['"']
    for b in s.encode("utf-8"):
        c = chr(b)
        if c == '"':    out.append('\\"')
        elif c == '\\': out.append('\\\\')
        elif c == '\n':  out.append('\\n')
        elif c == '\t':  out.append('\\t')
        elif c == '\r':  out.append('\\r')
        elif 0x20 <= b < 0x80:
            out.append(c)
        else:
            # Control chars AND non-ASCII bytes as explicit escapes; "" ends
            # the escape so a following digit can't extend it.
            out.append('\\x%02x""' % b)
    out.append('"')
    return "".join(out)

if __name__ == "__main__":
    dest = os.path.join(os.path.dirname(__file__), "..", "src", "i18n_catalogue.h")
    n = emit(os.path.abspath(dest))
    print("wrote %s" % os.path.abspath(dest))
    print("%d keys x %d languages" % (n, len(LANGS)))
